import itertools
def find_translations(B,S,H,W):
    out=[]
    for dr in range(-H,2*H):
        for dc in range(-W,2*W):
            if (dr,dc)==(0,0): continue
            # union of original + copies at k*(dr,dc), clipped; require copy0's cells match S within grid and extra cells only added
            U=set(B); moved=True; k=1
            while moved:
                moved=False
                nxt={(r+dr*k,c+dc*k) for r,c in B}
                vis={p for p in nxt if 0<=p[0]<H and 0<=p[1]<W}
                if not vis: break
                U|=vis; k+=1; moved=True
            if U==S: out.append((dr,dc))
    return out
