# Systematic search over small sets of translation vectors for demo1/demo2.
def stamps_search(B,S,H,W,vec_limit=3,max_k=25,vmax=6):
    sols=[]
    import itertools
    def build(vs):
        U=set(B); k=1
        while True:
            moved=False
            for v in vs:
                nxt={(r+v[0]*k,c+v[1]*k) for r,c in B}
                vis={p for p in nxt if 0<=p[0]<H and 0<=p[1]<W}
                if vis:
                    U|=vis; moved=True
            if not moved: break
            k+=1
            if k>max_k: break
        return U
    for n in (1,2,3):
        for combo in itertools.combinations([v for v in itertools.product(range(-vmax,vmax+1),repeat=2) if v!=(0,0)],n):
            try: sol=build(combo)
            except: continue
            if sol==S: sols.append(tuple(sorted(combo)))
    return sols
